#!/usr/bin/env bash
# Evaluation-hardening bundle (professor's question):
#   1) overhead-inclusive cost accounting in per_item()  [CORRECTNESS FIX]
#   2) scripts/ntc_operating_curves.py  — AUCC, coverage, matched-budget
#      accuracy, matched-accuracy budget B*, operating-curve figure
#   3) scripts/ntc_data_inventory.py    — exact dataset & protocol accounting
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing evaluation bundle..."
decode "apply_costfix.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_operating_curves.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_data_inventory.py" << 'B64EOF'

B64EOF
python apply_costfix.py && rm apply_costfix.py
echo ""
echo "Installed. Run the inventory, then the primary evaluation, then regenerate."